import { fetchAuditSignoff, saveAuditSignoff } from "@/features/audit/api";
import { AddManualActivityFlow } from "@/features/audit/learner-log-pro-copy/components/AddManualActivityFlow";
import { ManualActivityRow, ManualActivityTableHeader } from "@/features/audit/learner-log-pro-copy/components/ManualActivityRow";
import { RetrieveActivitiesPanel } from "@/features/audit/learner-log-pro-copy/components/RetrieveActivitiesPanel";
import { Button } from "@/features/audit/learner-log-pro-copy/components/ui/button";
import { Table, TableBody, TableHeader } from "@/features/audit/learner-log-pro-copy/components/ui/table";
import { getLearnerProfile, getLearners } from "@/features/audit/learner-log-pro-copy/lib/api";
import {
  bulkSaveManualRows,
  deleteAssignmentDocument,
  getManualRows,
  getManualSummary,
  manualRowToJournalActivity,
  uploadAssignmentDocument,
} from "@/features/audit/learner-log-pro-copy/lib/manualApi";
import {
  deleteDraftRow,
  draftFromServer,
  isDraftDirty,
  patchDraftRow,
  pendingChangeCount,
  rowPatchOf,
  stageDocumentDelete,
  stageFiles,
  unstageFile,
  visibleDraftRows,
  type DraftRow,
} from "@/features/audit/learner-log-pro-copy/lib/journalDraft";
import { downloadLearnerJournalPdf } from "@/features/audit/learner-log-pro-copy/lib/journal-pdf";

export const Route = createFileRoute("/journal/")({
  validateSearch: (search: Record<string, unknown>) => ({
    learner: typeof search.learner === "string" ? search.learner : "",
    period: typeof search.period === "string" ? search.period : "",
  }),
  component: JournalPage,
});

function SignatureCapture({ label, signer, value, onChange, onRemove, canRemove, isRemoving }: { label: string; signer: string; value: string; onChange: (value: string) => void; onRemove: () => void; canRemove: boolean; isRemoving: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const padRef = useRef<SignaturePad | null>(null);
  const onChangeRef = useRef(onChange);

  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ratio = Math.max(window.devicePixelRatio || 1, 1);
    const rect = canvas.getBoundingClientRect();
    canvas.width = Math.max(Math.floor(rect.width * ratio), 1);
    canvas.height = Math.max(Math.floor(rect.height * ratio), 1);
    canvas.getContext("2d")?.scale(ratio, ratio);
    const pad = new SignaturePad(canvas, {
      backgroundColor: "rgb(255, 255, 255)",
      penColor: "rgb(24, 45, 72)",
      minWidth: 0.8,
      maxWidth: 2.4,
      velocityFilterWeight: 0.7,
    });
    padRef.current = pad;
    const handleEndStroke = () => onChangeRef.current(pad.isEmpty() ? "" : pad.toDataURL("image/png"));
    pad.addEventListener("endStroke", handleEndStroke);
    return () => {
      pad.removeEventListener("endStroke", handleEndStroke);
      pad.off();
      padRef.current = null;
    };
  }, []);

  useEffect(() => {
    const pad = padRef.current;
    const canvas = canvasRef.current;
    if (!pad || !canvas) return;
    if (!value) {
      pad.clear();
      return;
    }
    const image = new Image();
    image.onload = () => {
      const context = canvas.getContext("2d");
      if (!context) return;
      pad.clear();
      context.drawImage(image, 0, 0, canvas.clientWidth, canvas.clientHeight);
    };
    image.src = value;
  }, [value]);

  return (
    <div className="rounded-lg border border-border bg-background/40 p-4">
      <div className="mb-3 flex items-start justify-between gap-4">
        <div>
          <p className="label-caps">{label}</p>
          <p className="mt-1 text-sm font-medium text-foreground">{signer || "—"}</p>
        </div>
        <div className="flex items-center gap-2">
          {canRemove && (
            <Button type="button" variant="outline" size="sm" disabled={isRemoving} onClick={onRemove} className="border-red-200 text-red-700 hover:bg-red-50 hover:text-red-800">
              <Trash2 className="h-3.5 w-3.5" /> Remove
            </Button>
          )}
          <Button type="button" variant="outline" size="sm" disabled={!value || isRemoving} onClick={() => { padRef.current?.clear(); onChange(""); }}>
            <RotateCcw className="h-3.5 w-3.5" /> Clear
          </Button>
        </div>
      </div>
      <div className="relative h-32 overflow-hidden rounded-md border border-border bg-white">
        <canvas ref={canvasRef} className="h-full w-full touch-none cursor-crosshair" aria-label={`${label} drawing area`} />
        {!value && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-muted-foreground/60">
            <PenLine className="mb-2 h-5 w-5" />
            <span className="text-xs">Sign here using mouse or touch</span>
          </div>
        )}
        <div className="pointer-events-none absolute inset-x-8 bottom-7 border-b border-dashed border-border" />
      </div>
    </div>
  );
}

