function hoursValue(value: number | null | undefined) {
  return value == null ? "—" : `${Number(value).toFixed(2)} h`;
}

function monthKeysBetween(start: string, end: string) {
  if (!/^\d{4}-\d{2}$/.test(start) || !/^\d{4}-\d{2}$/.test(end) || start > end) return [];
  const values: string[] = [];
  let year = Number(start.slice(0, 4));
  let month = Number(start.slice(5, 7));
  const endYear = Number(end.slice(0, 4));
  const endMonth = Number(end.slice(5, 7));
  while (year < endYear || (year === endYear && month <= endMonth)) {
    values.push(`${year}-${String(month).padStart(2, "0")}`);
    month += 1;
    if (month === 13) {
      month = 1;
      year += 1;
    }
  }
  return values;
}

function reportMonthLabel(month: string) {
  return new Date(`${month}-02T12:00:00`).toLocaleString("en-GB", { month: "long", year: "numeric" });
}

type AddChoice = "attendance" | "video" | "reading+quiz" | "audio" | "assignment" | "manual";

const ADD_CHOICES = [
  { value: "attendance", label: "Attendance day", icon: CalendarDays },
  { value: "video", label: "Videos / recordings", icon: Video },
  { value: "reading+quiz", label: "Reading + Quiz", icon: BookOpenText },
  { value: "audio", label: "Audio", icon: Headphones },
  { value: "assignment", label: "Assignment", icon: ClipboardList },
  { value: "manual", label: "Manual activity", icon: Plus },
] as const;

function ActivityAddMenu({ disabled, onPick }: { disabled: boolean; onPick: (choice: AddChoice) => void }) {
  const [open, setOpen] = useState(false);
  const menuRef = useRef<HTMLSpanElement | null>(null);
  useEffect(() => {
    const close = (event: MouseEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, []);
  return (
    <span ref={menuRef} className="relative">
      <Button size="sm" variant="outline" disabled={disabled} onClick={() => setOpen((value) => !value)}><Plus className="h-3.5 w-3.5" /> Add</Button>
      {open ? (
        <span className="absolute right-0 top-9 z-30 block w-56 rounded-md border border-border bg-card py-1 shadow-panel">
          {ADD_CHOICES.map((item) => <button key={item.value} type="button" onClick={() => { setOpen(false); onPick(item.value); }} className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm text-foreground hover:bg-secondary"><item.icon className="h-4 w-4 text-muted-foreground" />{item.label}</button>)}
        </span>
      ) : null}
    </span>
  );
}

function ActivityFlowModal({ onClose, children }: { onClose: () => void; children: ReactNode }) {
  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" role="dialog" aria-modal="true" onMouseDown={onClose}>
      <div className="max-h-[90vh] w-full max-w-6xl overflow-y-auto rounded-xl border border-border bg-card shadow-2xl" onMouseDown={(event) => event.stopPropagation()}>
        {children}
      </div>
    </div>
  );
}

function JournalPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const routeSearch = Route.useSearch();
  const [learnerChoice, setLearnerChoice] = useState(routeSearch.learner);
  const [periodChoice, setPeriodChoice] = useState(routeSearch.period);
  const [hoursTab, setHoursTab] = useState<"original" | "arranged">("original");
  const [addChoice, setAddChoice] = useState<AddChoice | null>(null);
  const [draftRows, setDraftRows] = useState<DraftRow[]>([]);
  const [isSavingAll, setIsSavingAll] = useState(false);
  const [isPreparingPdf, setIsPreparingPdf] = useState(false);
  const [learnerSignature, setLearnerSignature] = useState("");
  const [coachSignature, setCoachSignature] = useState("");
  const [learnerSignatureSaved, setLearnerSignatureSaved] = useState(false);
  const [coachSignatureSaved, setCoachSignatureSaved] = useState(false);
  const [isSavingSignatures, setIsSavingSignatures] = useState(false);
  const [signatureError, setSignatureError] = useState("");
  const signaturesSaved = learnerSignatureSaved && coachSignatureSaved;

  const metadata = useQuery({ queryKey: ["journal-metadata"], queryFn: () => getLearners() });
  useEffect(() => {
    if (!metadata.data || learnerChoice) return;
    if (metadata.data.learners[0]) setLearnerChoice(metadata.data.learners[0].id);
  }, [metadata.data, learnerChoice]);

  const selectedLearner = learnerChoice;
  const aptemId = Number(selectedLearner) || null;
  const learnerProfile = useQuery({
    queryKey: ["learner-profile", selectedLearner],
    queryFn: () => getLearnerProfile(selectedLearner),
    enabled: Boolean(selectedLearner),
    retry: false,
  });

  // Original planned months + employee-arranged sums, straight from the
  // manual ledger. This drives the month selector, so the report and its
  // selector always agree on which months exist.
  const summary = useQuery({
    queryKey: ["manual-summary", aptemId],
    queryFn: () => getManualSummary(aptemId!),
    enabled: Boolean(aptemId),
  });
  const learnerStartDate = learnerProfile.data?.learning_delivery.start_date
    ?? learnerProfile.data?.contracts.find((contract) => contract.programme_start_date)?.programme_start_date
    ?? "";
  const learnerStartMonth = learnerStartDate.slice(0, 7);
  const summaryMonths = useMemo(() => {
    const available = summary.data?.months ?? [];
    if (!learnerStartMonth || !available.length) return available;
    const availableByMonth = new Map(available.map((item) => [item.month, item]));
    const endMonth = available.reduce(
      (latest, item) => item.month > latest ? item.month : latest,
      available[0].month,
    );
    return monthKeysBetween(learnerStartMonth, endMonth).map((month) => availableByMonth.get(month) ?? {
      month,
      label: reportMonthLabel(month),
      original_planned: null,
      arranged_planned: 0,
      arranged_actual: 0,
      arranged_not_accepted: 0,
      row_count: 0,
    });
  }, [summary.data?.months, learnerStartMonth]);
  const selectedPeriod = summaryMonths.some((item) => item.month === periodChoice) ? periodChoice : "";

  useEffect(() => {
    if (!summary.data) return;
    if (summaryMonths.some((item) => item.month === periodChoice)) return;
    setPeriodChoice(summaryMonths[summaryMonths.length - 1]?.month ?? "");
    setLearnerSignature("");
    setCoachSignature("");
    setLearnerSignatureSaved(false);
    setCoachSignatureSaved(false);
  }, [summary.data, summaryMonths, periodChoice]);

  const manualRows = useQuery({
    queryKey: ["manual-rows", aptemId, selectedPeriod],
    queryFn: () => getManualRows(aptemId!, selectedPeriod),
    enabled: Boolean(aptemId && selectedPeriod),
  });

  const dirty = isDraftDirty(draftRows);
  // Seed / refresh the draft from the server ONLY while it holds no unsaved
  // work, so a background refetch never clobbers the employee's edits.
  useEffect(() => {
    if (!manualRows.data || dirty) return;
    setDraftRows(manualRows.data.rows.map(draftFromServer));
  }, [manualRows.data, dirty]);

  const visibleRows = visibleDraftRows(draftRows).sort((left, right) => {
    const leftDate = left.activity_date || "9999-12-31";
    const rightDate = right.activity_date || "9999-12-31";
    return leftDate.localeCompare(rightDate) || left.title.localeCompare(right.title);
  });
  const existingRefs = useMemo(
    () => new Set(visibleRows.map((row) => row.source_ref).filter(Boolean) as string[]),
    [visibleRows],
  );

  async function confirmDiscardIfDirty(): Promise<boolean> {
    if (!dirty) return true;
    const confirmation = await Swal.fire({
      icon: "warning",
      title: "Discard unsaved changes?",
      text: "This month's draft has unsaved changes. Leaving now throws them away.",
      showCancelButton: true,
      confirmButtonText: "Discard changes",
      cancelButtonText: "Keep editing",
      confirmButtonColor: "#b91c1c",
      reverseButtons: true,
    });
    return confirmation.isConfirmed;
  }
  const savedSignoff = useQuery({
    queryKey: ["journal-signoff", selectedLearner, selectedPeriod],
    queryFn: () => fetchAuditSignoff(selectedLearner, selectedPeriod),
    enabled: Boolean(selectedLearner && selectedPeriod),
    retry: false,
  });

  useEffect(() => {
    if (!savedSignoff.data) return;
    const savedLearnerSignature = savedSignoff.data.signoffs.learner?.signature_data ?? "";
    const savedCoachSignature = savedSignoff.data.signoffs.coach?.signature_data ?? "";
    setLearnerSignature(savedLearnerSignature);
    setCoachSignature(savedCoachSignature);
    setLearnerSignatureSaved(Boolean(savedLearnerSignature));
    setCoachSignatureSaved(Boolean(savedCoachSignature));
    setSignatureError("");
  }, [savedSignoff.data]);

  const learnerName = summary.data?.learner_name
    ?? metadata.data?.learners.find((item) => item.id === selectedLearner)?.name
    ?? "";
  const selectedMonth = summaryMonths.find((item) => item.month === selectedPeriod);
  const monthLabel = selectedMonth?.label ?? "No report months";
  // All month figures come from the DRAFT so the employee sees the effect of
  // unsaved work live; after a save the draft mirrors the server exactly.
  const round2 = (value: number) => Math.round(value * 100) / 100;
  const arrangedPlanned = round2(visibleRows.reduce((sum, row) => sum + row.planned_hours, 0));
  const acceptedActual = round2(visibleRows.filter((row) => row.accepted).reduce((sum, row) => sum + row.actual_hours, 0));
  const notAcceptedActual = round2(visibleRows.filter((row) => !row.accepted).reduce((sum, row) => sum + row.actual_hours, 0));
  const arrangedActual = acceptedActual;
  const originalPlanned = selectedMonth?.original_planned ?? null;
  const plannedVariance = originalPlanned == null ? null : round2(arrangedPlanned - originalPlanned);

  async function handleSaveAll() {
    if (!aptemId || !dirty || isSavingAll) return;
    setIsSavingAll(true);
    try {
      const creates = draftRows
        .filter((row) => row.state === "new")
        .map((row) => ({
          key: row.key,
          month: row.month,
          category: row.category,
          source_ref: row.source_ref,
          title: row.title,
          activity_date: row.activity_date,
          planned_hours: row.planned_hours,
          actual_hours: row.actual_hours,
          timestamp_label: row.timestamp_label,
          completion_note: row.completion_note,
          accepted: row.accepted,
        }));
      const updates = draftRows
        .filter((row) => row.state === "edited" && row.serverId != null)
        .map((row) => ({ id: row.serverId!, patch: rowPatchOf(row) }));
      const deletes = draftRows
        .filter((row) => row.state === "deleted" && row.serverId != null)
        .map((row) => row.serverId!);
      const result = await bulkSaveManualRows({ aptem_id: aptemId, creates, updates, deletes });

      // Flush staged uploads / document removals now that ids exist.
      const createdIdByKey = new Map(result.created.map((item) => [item.key, item.row.id]));
      const failedUploads: string[] = [];
      for (const row of draftRows) {
        if (row.state === "deleted") continue;
        const targetId = row.serverId ?? createdIdByKey.get(row.key);
        if (targetId != null) {
          for (const file of row.stagedFiles) {
            try {
              await uploadAssignmentDocument(targetId, file);
            } catch {
              failedUploads.push(file.name);
            }
          }
        }
        for (const docId of row.deletedDocIds) {
          try {
            await deleteAssignmentDocument(docId);
          } catch {
            failedUploads.push(`remove #${docId}`);
          }
        }
      }

      setDraftRows([]); // clean slate — the refetch below reseeds it
      await queryClient.invalidateQueries({ queryKey: ["manual-rows"] });
      await queryClient.invalidateQueries({ queryKey: ["manual-summary"] });

      if (result.skipped.length || failedUploads.length) {
        const parts = [];
        if (result.skipped.length) parts.push(`${result.skipped.length} duplicate row(s) were already on the report and were skipped.`);
        if (failedUploads.length) parts.push(`These uploads failed — retry from the row: ${failedUploads.join(", ")}.`);
        await Swal.fire({ icon: "warning", title: "Saved with warnings", text: parts.join(" ") });
      } else {
        await Swal.fire({ toast: true, position: "top-end", icon: "success", title: "All activities saved", showConfirmButton: false, timer: 2000 });
      }
    } catch (error) {
      await Swal.fire({ icon: "error", title: "Could not save the journal", text: error instanceof Error ? error.message : "Could not save the journal changes." });
    } finally {
      setIsSavingAll(false);
    }
  }

  async function handleDiscard() {
    if (!(await confirmDiscardIfDirty())) return;
    setDraftRows(manualRows.data ? manualRows.data.rows.map(draftFromServer) : []);
  }

  async function handleDownloadPdf() {
    if (!learnerProfile.data || !selectedLearner || !selectedPeriod || !manualRows.data) return;
    setIsPreparingPdf(true);
    try {
      const pdfRows = (manualRows.data.rows ?? []).map(manualRowToJournalActivity);
      const pdfSummary = {
        name: learnerName,
        planned_hours: originalPlanned ?? 0,
        actual_hours: Math.round(acceptedActual * 100) / 100,
        gap_hours: Math.round((acceptedActual - (originalPlanned ?? 0)) * 100) / 100,
        not_accepted_hours: Math.round(notAcceptedActual * 100) / 100,
      };
      await downloadLearnerJournalPdf(pdfSummary, monthLabel, pdfRows, undefined, learnerProfile.data, {
        learner: learnerSignature,
        coach: coachSignature,
      });
    } finally {
      setIsPreparingPdf(false);
    }
  }

  async function handleSaveSignatures() {
    const signoffAptemId = learnerProfile.data?.aptem_id;
    if (!signoffAptemId || !learnerName || !learnerSignature || !coachSignature) return;
    setIsSavingSignatures(true);
    setSignatureError("");
    try {
      const now = new Date().toISOString();
      const response = await saveAuditSignoff(signoffAptemId, {
        monthKey: selectedPeriod,
        roles: {
          learner: { signerName: learnerName, signature: learnerSignature, confirmed: true, signedAt: now },
          coach: { signerName: learnerProfile.data?.coach.name ?? "", signature: coachSignature, confirmed: true, signedAt: now },
        },
      });
      queryClient.setQueryData(["journal-signoff", signoffAptemId, selectedPeriod], response);
      setLearnerSignature(response.signoffs.learner?.signature_data ?? learnerSignature);
      setCoachSignature(response.signoffs.coach?.signature_data ?? coachSignature);
      setLearnerSignatureSaved(Boolean(response.signoffs.learner?.signature_data));
      setCoachSignatureSaved(Boolean(response.signoffs.coach?.signature_data));
    } catch (error) {
      setSignatureError(error instanceof Error ? error.message : "Could not save the signatures.");
      setLearnerSignatureSaved(false);
      setCoachSignatureSaved(false);
    } finally {
      setIsSavingSignatures(false);
    }
  }

  async function handleRemoveSignature(role: "learner" | "coach") {
    const signoffAptemId = learnerProfile.data?.aptem_id;
    if (!signoffAptemId || !learnerName) return;
    const roleLabel = role === "learner" ? "learner" : "coach";
    const confirmation = await Swal.fire({
      icon: "warning",
      title: `Remove ${roleLabel} signature?`,
      text: `This removes the saved ${roleLabel} signature for ${monthLabel}.`,
      showCancelButton: true,
      confirmButtonText: "Yes, remove it",
      cancelButtonText: "Cancel",
      confirmButtonColor: "#b91c1c",
      reverseButtons: true,
    });
    if (!confirmation.isConfirmed) return;
    setIsSavingSignatures(true);
    setSignatureError("");
    try {
      const nextLearnerSignature = role === "learner" ? "" : learnerSignature;
      const nextCoachSignature = role === "coach" ? "" : coachSignature;
      const now = new Date().toISOString();
      const response = await saveAuditSignoff(signoffAptemId, {
        monthKey: selectedPeriod,
        roles: {
          learner: { signerName: learnerName, signature: nextLearnerSignature, confirmed: Boolean(nextLearnerSignature), signedAt: nextLearnerSignature ? now : "" },
          coach: { signerName: learnerProfile.data?.coach.name ?? "", signature: nextCoachSignature, confirmed: Boolean(nextCoachSignature), signedAt: nextCoachSignature ? now : "" },
        },
      });
      queryClient.setQueryData(["journal-signoff", signoffAptemId, selectedPeriod], response);
      setLearnerSignature(response.signoffs.learner?.signature_data ?? "");
      setCoachSignature(response.signoffs.coach?.signature_data ?? "");
      setLearnerSignatureSaved(Boolean(response.signoffs.learner?.signature_data));
      setCoachSignatureSaved(Boolean(response.signoffs.coach?.signature_data));
      await Swal.fire({ icon: "success", title: "Signature removed", text: `The ${roleLabel} signature was removed successfully.`, timer: 1800, showConfirmButton: false });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Could not remove the signature.";
      setSignatureError(message);
      await Swal.fire({ icon: "error", title: "Could not remove signature", text: message });
    } finally {
      setIsSavingSignatures(false);
    }
  }

  const isLoading =
    metadata.isLoading ||
    (Boolean(aptemId) && summary.isLoading) ||
    (Boolean(aptemId && selectedPeriod) && manualRows.isLoading) ||
    (Boolean(selectedLearner) && learnerProfile.isLoading) ||
    (Boolean(learnerProfile.data?.aptem_id && selectedPeriod) && savedSignoff.isLoading);
  // Rich profile/sign-off data is optional for newly added programmes. Core
  // summary/row failures still block the journal; optional 404s do not.
  const pageError = metadata.error || summary.error || manualRows.error;

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="flex w-full flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Employee-arranged learner journal</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
            <Link to="/activity" search={{ learner: selectedLearner }} className="font-medium hover:underline">Activity log</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1700px] space-y-6 px-6 py-8">
        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
          <div className="h-1 bg-[#182d48]" />
          <div className="flex flex-wrap items-center justify-between gap-6 px-7 py-6">
            <div className="flex items-center gap-5">
              <img src="/assets/kbc-logo.png" alt="Kent Business College" className="h-16 w-36 object-contain object-left" />
              <span className="h-14 w-px bg-border" />
              <div>
                <h1 className="text-2xl font-semibold tracking-tight text-[#182d48]">Learner Journal</h1>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="rounded-xl bg-[#f6f8fb] px-6 py-3 text-center">
                <p className="text-[9px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Reporting month</p>
                <p className="mt-1 text-sm font-semibold text-[#182d48]">{metadata.isLoading || summary.isLoading ? "Loading…" : monthLabel}</p>
              </div>
              <Button
                className="gap-2 bg-[#182d48] hover:bg-[#243f61]"
                disabled={!manualRows.data || !learnerProfile.data || !signaturesSaved || isPreparingPdf || dirty}
                title={dirty ? "Save all activities first — the PDF only includes saved rows" : undefined}
                onClick={handleDownloadPdf}
              >
                {isPreparingPdf ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                {isPreparingPdf ? "Preparing PDF..." : "Download PDF"}
              </Button>
            </div>
          </div>

          <div className="grid gap-4 border-y border-border bg-[#fafbfc] px-7 py-5 sm:grid-cols-2">
            <label><span className="label-caps">Learner</span><select className="mt-1.5 h-9 w-full rounded-md border border-border bg-card px-3 text-sm" value={selectedLearner} onChange={async (event) => { const next = event.target.value; if (!(await confirmDiscardIfDirty())) { event.target.value = selectedLearner; return; } setDraftRows([]); setLearnerChoice(next); setPeriodChoice(""); setAddingActivity(false); setRetrieving(false); setLearnerSignature(""); setCoachSignature(""); setLearnerSignatureSaved(false); setCoachSignatureSaved(false); }}>{metadata.data?.learners.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
            <label><span className="label-caps">Report month</span><select className="mt-1.5 h-9 w-full rounded-md border border-border bg-card px-3 text-sm disabled:cursor-not-allowed disabled:opacity-60" value={selectedPeriod} disabled={!summaryMonths.length} onChange={async (event) => { const next = event.target.value; if (!(await confirmDiscardIfDirty())) { event.target.value = selectedPeriod; return; } setDraftRows([]); setPeriodChoice(next); setAddingActivity(false); setRetrieving(false); setLearnerSignature(""); setCoachSignature(""); setLearnerSignatureSaved(false); setCoachSignatureSaved(false); }}>{summaryMonths.length ? summaryMonths.map((item) => <option key={item.month} value={item.month}>{item.label}</option>) : <option value="">No report months available</option>}</select></label>
          </div>

          {pageError ? (
            <p className="py-10 text-center text-sm text-destructive">
              {pageError instanceof Error ? pageError.message : "Could not load the journal."}
            </p>
          ) : selectedLearner && summary.data && !summaryMonths.length ? (
            <p className="py-10 text-center text-sm text-muted-foreground">No planned months or arranged activities exist for this learner yet.</p>
          ) : isLoading || !selectedLearner || !selectedPeriod ? (
            <p className="py-10 text-center text-sm text-muted-foreground">Loading journal…</p>
          ) : summary.data ? (
            <div className="space-y-5 px-7 py-6">
              <div className="grid rounded-lg bg-[#f6f8fb] px-5 lg:grid-cols-3">
                <ProfileGroup label="Learner" value={learnerName} secondaryLabel="Start date" secondaryValue={learnerProfile.data?.learning_delivery.start_date ?? "—"} />
                <ProfileGroup label="Programme" value={summary.data.programme_name ?? learnerProfile.data?.programme ?? "—"} secondaryLabel="First evidence" secondaryValue={learnerProfile.data?.learning_delivery.first_evidence_date ?? "—"} />
                <ProfileGroup label="Coach" value={summary.data.coach_name ?? learnerProfile.data?.coach.name ?? "—"} secondaryLabel="Planned end" secondaryValue={learnerProfile.data?.learning_delivery.planned_end_date ?? "—"} />
              </div>

              <div className="flex items-center gap-1 rounded-lg bg-[#f6f8fb] p-1 text-xs font-semibold sm:w-fit">
                <button type="button" onClick={() => setHoursTab("original")} className={`rounded-md px-4 py-2 transition-colors ${hoursTab === "original" ? "bg-[#182d48] text-white" : "text-muted-foreground hover:text-foreground"}`}>Original plan</button>
                <button type="button" onClick={() => setHoursTab("arranged")} className={`rounded-md px-4 py-2 transition-colors ${hoursTab === "arranged" ? "bg-[#182d48] text-white" : "text-muted-foreground hover:text-foreground"}`}>Employee arranged</button>
              </div>

              {hoursTab === "original" ? (
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                  <Stat label="Original monthly plan" value={hoursValue(originalPlanned)} />
                  <Stat label="Programme planned total" value={hoursValue(summary.data.planned_hours_total)} />
                  <Stat label="Arranged this month" value={hoursValue(arrangedPlanned)} tone="purple" />
                  <Stat
                    label="Plan variance"
                    value={plannedVariance == null ? "—" : `${plannedVariance > 0 ? "+" : ""}${plannedVariance.toFixed(2)} h`}
                    tone={plannedVariance != null && plannedVariance < 0 ? "warning" : "success"}
                  />
                </div>
              ) : (
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                  <Stat label="Accumulative planned" value={hoursValue(arrangedPlanned)} tone="purple" />
                  <Stat label="Actual (claimed)" value={hoursValue(arrangedActual)} tone="success" />
                  <Stat label="Not accepted" value={hoursValue(notAcceptedActual)} tone="warning" />
                  <Stat label="Activities this month" value={String(visibleRows.length)} />
                </div>
              )}
            </div>
          ) : null}
        </section>

        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
          <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
            <div>
              <h2 className="text-lg font-semibold text-[#182d48]">Activity log</h2>
              <p className="mt-1 text-sm text-muted-foreground">Activities the audit team arranged onto this month's report</p>
            </div>
            <div className="flex items-center gap-2">
              <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono text-xs font-medium text-[#182d48]">{visibleRows.length} activities</span>
              <ActivityAddMenu disabled={!aptemId || !selectedPeriod} onPick={setAddChoice} />
            </div>
          </header>
          {addChoice && ["attendance", "video", "reading+quiz", "audio"].includes(addChoice) && aptemId && selectedPeriod ? (
            <ActivityFlowModal onClose={() => setAddChoice(null)}>
              <RetrieveActivitiesPanel
                key={addChoice}
                aptemId={aptemId}
                month={selectedPeriod}
                monthLabel={monthLabel}
                existingRefs={existingRefs}
                initialCategory={addChoice as "attendance" | "video" | "reading+quiz" | "audio"}
                onRetrieve={(rows) => setDraftRows((current) => [...current, ...rows])}
                onClose={() => setAddChoice(null)}
              />
            </ActivityFlowModal>
          ) : null}
          {(addChoice === "assignment" || addChoice === "manual") && aptemId && selectedPeriod ? (
            <ActivityFlowModal onClose={() => setAddChoice(null)}>
              <AddManualActivityFlow
                key={addChoice}
                aptemId={aptemId}
                month={selectedPeriod}
                monthLabel={monthLabel}
                existingRefs={existingRefs}
                initialCategory={addChoice === "assignment" ? "assignment" : "attendance"}
                manualEntry={addChoice === "manual"}
                onAdd={(row) => setDraftRows((current) => [...current, row])}
                onClose={() => setAddChoice(null)}
              />
            </ActivityFlowModal>
          ) : null}
          <div className="overflow-x-auto">
            <Table>
              <TableHeader><ManualActivityTableHeader dark /></TableHeader>
              <TableBody>
                {visibleRows.map((row) => (
                  <ManualActivityRow
                    key={row.key}
                    row={row}
                    className="odd:bg-[#f7f9fc]"
                    onPatch={(patch) => setDraftRows((current) => patchDraftRow(current, row.key, patch))}
                    onDelete={() => setDraftRows((current) => deleteDraftRow(current, row.key))}
                    onStageFiles={(files) => setDraftRows((current) => stageFiles(current, row.key, files))}
                    onUnstageFile={(index) => setDraftRows((current) => unstageFile(current, row.key, index))}
                    onDeleteDocument={(docId) => setDraftRows((current) => stageDocumentDelete(current, row.key, docId))}
                  />
                ))}
              </TableBody>
            </Table>
            {!visibleRows.length && !manualRows.isLoading ? (
              <p className="py-10 text-center text-sm text-muted-foreground">No activities on this month yet — use “Add” to arrange the first one.</p>
            ) : null}
          </div>
          <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-7 py-4">
            <p className="text-xs text-muted-foreground">
              <span className="font-mono font-medium text-foreground">{visibleRows.length}</span> activities ·
              planned <span className="font-mono font-medium text-foreground">{hoursValue(arrangedPlanned)}</span> ·
              claimed <span className="font-mono font-medium text-foreground">{hoursValue(acceptedActual)}</span>
              {dirty ? <span className="ml-2 rounded-full bg-amber-500/15 px-2 py-0.5 text-[10px] font-semibold text-amber-700">unsaved draft</span> : null}
            </p>
          </footer>
        </section>

        <section className="rounded-xl border border-border bg-card p-7 shadow-panel">
          <div className="mb-5 flex flex-wrap items-start justify-between gap-4">
            <div>
              <h2 className="text-lg font-semibold text-[#182d48]">Report sign-off</h2>
              <p className="mt-1 text-sm text-muted-foreground">Saved for this learner and month, then embedded in every downloaded PDF.</p>
              {signatureError && <p className="mt-2 text-xs text-destructive">{signatureError}</p>}
            </div>
            <div className="flex items-center gap-2">
              <Button
                type="button"
                disabled={!learnerSignature || !coachSignature || isSavingSignatures || signaturesSaved || dirty}
                title={dirty ? "Save all activities first — the sign-off covers saved rows" : undefined}
                onClick={handleSaveSignatures}
                className="min-w-36 bg-[#182d48] hover:bg-[#243f61]"
              >
                {isSavingSignatures ? <LoaderCircle className="h-4 w-4 animate-spin" /> : signaturesSaved ? <CheckCircle2 className="h-4 w-4" /> : <Save className="h-4 w-4" />}
                {isSavingSignatures ? "Saving..." : signaturesSaved ? "Saved" : "Save signatures"}
              </Button>
            </div>
          </div>
          <div className="grid gap-4 lg:grid-cols-2">
            <SignatureCapture label="Learner signature" signer={learnerName} value={learnerSignature} onChange={(value) => { setLearnerSignature(value); setLearnerSignatureSaved(false); }} onRemove={() => handleRemoveSignature("learner")} canRemove={learnerSignatureSaved} isRemoving={isSavingSignatures} />
            <SignatureCapture label="Coach signature" signer={learnerProfile.data?.coach.name ?? ""} value={coachSignature} onChange={(value) => { setCoachSignature(value); setCoachSignatureSaved(false); }} onRemove={() => handleRemoveSignature("coach")} canRemove={coachSignatureSaved} isRemoving={isSavingSignatures} />
          </div>
        </section>
      </main>

      {/* Nothing persists until this floating save flushes the whole draft. */}
      {dirty ? (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 shadow-2xl">
          <span className="flex items-center gap-2 text-sm text-foreground">
            <span className="h-2 w-2 animate-pulse rounded-full bg-amber-500" />
            <span className="font-mono font-semibold">{pendingChangeCount(draftRows)}</span> unsaved change{pendingChangeCount(draftRows) === 1 ? "" : "s"}
          </span>
          <Button variant="outline" size="sm" disabled={isSavingAll} onClick={handleDiscard}>Discard</Button>
          <Button size="sm" className="gap-1.5 bg-[#182d48] hover:bg-[#243f61]" disabled={isSavingAll} onClick={handleSaveAll}>
            {isSavingAll ? <LoaderCircle className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
            {isSavingAll ? "Saving…" : "Save all activities"}
          </Button>
        </div>
      ) : null}
    </div>
  );
}
